export const INGREDIENT_DICTIONARY = [...RAW_ENTRIES, ...EXTRA_CULINARY].map(
  ([name, aliases, category, status, reason]) => ({
    name,
    normalizedName: name.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim(),
    aliases: aliases.map((a) => a.toLowerCase()),
    category,
    status, // 'beneficial' | 'neutral' | 'harmful' | 'banned_wada'
    reason,
  })
);

// Fast exact-lookup map for normalized names, aliases, and E-numbers
export const EXACT_INGREDIENT_MAP = new Map();
for (const entry of INGREDIENT_DICTIONARY) {
  EXACT_INGREDIENT_MAP.set(entry.normalizedName, entry);
  for (const alias of entry.aliases) {
    const cleanAlias = alias.replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
    if (cleanAlias && !EXACT_INGREDIENT_MAP.has(cleanAlias)) {
      EXACT_INGREDIENT_MAP.set(cleanAlias, entry);
    }
  }
}

// Flat search corpus for Fuse.js (canonical names + aliases)
export const DICTIONARY_SEARCH_ITEMS = INGREDIENT_DICTIONARY.flatMap((entry) => [
  { term: entry.normalizedName, entry },
  ...entry.aliases.map((alias) => ({
    term: alias.replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim(),
    entry,
  })),
]).filter((item) => item.term.length >= 2);
